// Provider brand marks — the model vendors' own logos (ported from the composer's model picker so
// the catalog, routes, and model identity render the same mark instead of a bare text pill) plus the
// sign-in providers (Google, GitHub) so the login screen, the org settings page, and the admin org
// register all render one canonical mark instead of each copying the SVG geometry.
//
// Inline SVGs (the brand convention, see the brand logos) rather than asset-URL imports, so the marks
// render with no dependency on the consuming app's Vite asset pipeline. The two source marks fill
// their artboards differently: the Anthropic blossom is full-bleed in a 1200² box and keeps its
// brand vermilion (#d97757, which reads on both light + dark surfaces); the OpenAI monoblossom is
// recolored to `currentColor` (the source ships separate black + white marks — one currentColor
// mark covers both themes) and its viewBox is cropped to the ink bounds so the two read at matching
// optical weight at the same px box.
//
// These are third-party trademarks (Anthropic, OpenAI). They are used unmodified in geometry, the
// same marks the composer already ships; recoloring OpenAI to currentColor is the one concession for
// a monochrome UI context. `bedrock` and any unknown provider have no mark and resolve to null so the
// caller can fall back to a bench-line glyph.

import type { CSSProperties, ReactNode } from "react";

import { cx } from "../../primitives/cx";

export interface ProviderMarkProps {
  /** Rendered px box (width = height). Default 16. */
  size?: number;
  /** Accessible name. When set the mark is `role="img"`; omit for a decorative mark (aria-hidden). */
  title?: string;
  /** Merged onto the svg so a caller can override sizing/colour (a standing rule for every base). */
  className?: string;
  style?: CSSProperties;
}

