/** Anthropic blossom — single fill path in the brand vermilion (#d97757), intentional and theme-agnostic. */
export function AnthropicMark({ size = 16, title, className, style }: ProviderMarkProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 1200 1200"
      className={cx("alk-provider-mark", className)}
      style={style}
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      focusable="false"
    >
      <path fill="#d97757" d={ANTHROPIC_PATH} />
    </svg>
  );
}

/** OpenAI monoblossom — single path recolored to `currentColor`, viewBox cropped to the ink bounds. */
export function OpenAiMark({ size = 16, title, className, style }: ProviderMarkProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox={`${OPENAI_INK.x} ${OPENAI_INK.y} ${OPENAI_INK.w} ${OPENAI_INK.h}`}
      className={cx("alk-provider-mark", className)}
      style={style}
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      focusable="false"
    >
      <path fill="currentColor" d={OPENAI_PATH} />
    </svg>
  );
}

