/** Resolve a provider/family/model string to its brand mark, or `null` when none exists (bedrock,
 *  unknown families) so the caller can fall back to a bench-line glyph. Token-based like the composer:
 *  matches `anthropic`/`claude` and `openai`/`gpt` as substrings so a model id or a family both hit. */
export function resolveProviderMark(value: string, props?: ProviderMarkProps): ReactNode | null {
  const v = value.toLowerCase();
  if (v.includes("anthropic") || v.includes("claude")) return <AnthropicMark {...props} />;
  if (v.includes("openai") || v.includes("gpt") || v.includes("codex")) return <OpenAiMark {...props} />;
  return null;
}
